use tracing_test::traced_test;
use tempfile::tempdir;

#[traced_test]
#[tokio::test]
async fn test_export_pipeline_complete_success() {
    // Setup
    let session = load_test_session("fixtures/real_sessions/claude_code_auth_fix.jsonl");
    let output_dir = tempdir().unwrap();
    let options = ExportOptions {
        output_dir: Some(output_dir.path().to_path_buf()),
        ..Default::default()
    };

    // Execute
    let result = export_session_to_html(&session, &options).await;

    // Verify success
    assert!(result.is_ok(), "Export failed: {:?}", result.err());
    let export_result = result.unwrap();

    // Verify file exists and is valid HTML
    assert!(export_result.output_path.exists());
    let html = std::fs::read_to_string(&export_result.output_path).unwrap();
    assert!(html.starts_with("<!DOCTYPE html>"));
    assert!(html.contains("</html>"));

    // Verify content preserved
    for msg in &session.messages {
        // Check that message content appears (escaped) in output
        let escaped_preview = escape_html(&msg.content[..100.min(msg.content.len())]);
        assert!(html.contains(&escaped_preview),
            "Message content not found in output");
    }

    // Verify logging captured all stages
    assert!(logs_contain("component=template operation=generate"));
    assert!(logs_contain("component=renderer operation=render_conversation"));
    assert!(logs_contain("component=file operation=write_complete"));
    assert!(logs_contain("duration_ms="));

    // Log export summary
    tracing::info!(
        output_path = %export_result.output_path.display(),
        size_bytes = export_result.size_bytes,
        messages = session.messages.len(),
        "Integration test export complete"
    );
}

