    let messages_per_sec = 1000.0 / elapsed.as_secs_f64();
    assert!(messages_per_sec > 100.0,
        "Too slow: {} msg/s", messages_per_sec);

    tracing::info!(
        elapsed_ms = elapsed.as_millis(),
        messages_per_sec = messages_per_sec,
        "Large session benchmark"
    );
}
